brand_css_dark:
:root {
--radius-none: 0;
--radius-sm: 4px;      /* 칩·배지·이미지 카운터 */
--radius-md: 8px;      /* 버튼·입력·작은 카드 */
--radius-lg: 16px;     /* 기사 카드·위젯 (rounded-lg 48회 최다) */
--radius-xl: 32px;     /* 큰 프로모션 패널 */
--radius-search: 26px; /* 검색 버튼 60×40 */
--radius-full: 9999px; /* 검색창(100px)·아바타 */
--shadow-none: none;
--shadow-sm: 0 0 1px 0 rgba(0,0,0,0.35), 0 1px 2px 0 rgba(0,0,0,0.24);                                  /* elevation-1 — 기사 카드 */
--shadow-md: 0 0 1px 0 rgba(0,0,0,0.35), 0 2px 4px -1px rgba(0,0,0,0.30), 0 4px 8px -2px rgba(0,0,0,0.24); /* elevation-2 — 검색창 hover·드롭다운 */
--shadow-lg: 0 0 1px 0 rgba(0,0,0,0.35), 0 8px 16px -4px rgba(0,0,0,0.35), 0 12px 24px -6px rgba(0,0,0,0.30); /* elevation-3 — 팝오버 (추정) */
--shadow-xl: 0 24px 48px -12px rgba(0,0,0,0.60);                                                        /* 2xl — 모달 */
--duration-fast: 120ms;   /* 버튼 scale 1.03/0.97 (추정) */
--duration-base: 200ms;   /* 검색창 높이·아웃라인 전환 (실측 .2s/.3s) */
--duration-slow: 400ms;   /* 캐러셀 슬라이드 (추정) */
--ease-out: cubic-bezier(0.34, 1.4, 0.64, 1);   /* bouncy 스프링 근사 — 살짝 튕김 (추정) */
--ease-in-out: ease-in-out;                     /* 검색창 전환 실측 */
}
:root {
  /* Primary - Yahoo Purple (UDS purple spectrum, 다크) — 다크에선 brand 가 #957EFC 로 밝아진다 */
  --color-primary-50:  #1D0B3C;  /* purple-1 (dark) — 선택 행 배경 */
  --color-primary-100: #290F53;  /* purple-2 (dark) */
  --color-primary-200: #331368;  /* purple-3 (dark) */
  --color-primary-300: #4D1C9E;  /* purple-5 (dark) */
  --color-primary-400: #907CFF;  /* purple-9 (dark) */
  --color-primary-500: #957EFC;  /* uds-brand-dark 폴백 rgb(149 126 252) — 검색 버튼·링크 (기본) */
  --color-primary-600: #A47EFF;  /* purple-10 (dark) — hover */
  --color-primary-700: #C8B0FF;  /* purple-12 (dark) */
  --color-primary-800: #DBCCFF;  /* purple-14 (dark) */
  --color-primary-900: #F0ECFE;  /* purple-15 (dark) */

  /* Secondary */
  --color-secondary-500: #7D2EFF;  /* 라이트 대표 보라 — 다크에서도 일러스트 강조에만 (추정) */
  --color-accent-500:    #12A9FF;  /* blue-9 (dark) */

  /* Neutral - 반전 (0 = 가장 어두움) */
  --color-neutral-0:    #101518;  /* midnight — uds background-secondary (dark) */
  --color-neutral-50:   #1D2228;  /* uds background-primary (dark) 29,34,40 */
  --color-neutral-100:  #232A31;  /* batcave */
  --color-neutral-300:  #2C363F;  /* bg-tertiary (dark) */
  --color-neutral-500:  #6E7780;  /* dolphin */
  --color-neutral-700:  #B0B9C1;  /* gray-10 (dark) */
  --color-neutral-900:  #F0F3F5;  /* grey-hair — 다크 본문 글자 */
  --color-neutral-1000: #FFFFFF;

  /* Semantic (다크 값은 일부 (추정)) */
  --color-success-bg: #10291C;  /* (추정) green 면 */
  --color-success-fg: #38AF65;  /* green-7 — 다크 대비용 (추정) */
  --color-warning-bg: #2A1308;  /* orange-15 */
  --color-warning-fg: #F5A357;  /* orange-6 (추정) */
  --color-error-bg:   #3B0200;  /* red-15 */
  --color-error-fg:   #EA7A6F;  /* red-7 (추정) */
  --color-info-bg:    #001339;  /* blue-1 (dark) */
  --color-info-fg:    #12A9FF;  /* blue-9 (dark) */

  /* Surface (배경 위계) */
  --bg-base:     #101518;             /* midnight — 다크 홈 배경 */
  --bg-subtle:   #1D2228;             /* 검색창 면 (uds-secondary-dark 계열) */
  --bg-elevated: #1D2228;             /* 카드 */
  --bg-overlay:  rgba(0, 0, 0, 0.7);  /* (추정) */

  /* Text 위계 */
  --text-primary:    #F0F3F5;  /* grey-hair — 다크 본문 */
  --text-secondary:  #B0B9C1;  /* gray-10 (dark) — placeholder(bob 계열) */
  --text-tertiary:   #91969B;  /* gray-10 (dark 대체값) */
  --text-on-primary: #FFFFFF;
  --text-disabled:   #464E56;

  /* Border */
  --border-default: #2C363F;
  --border-subtle:  #232A31;
  --border-strong:  #464E56;
  --border-focus:   #957EFC;  /* focus-visible rgb(149 126 252 / 80%) */
}

[data-theme="light"] {
  /* Primary - Yahoo Purple (UDS purple spectrum, 라이트) */
  --color-primary-50:  #F3F0FE;  /* purple-1 — 선택 행·브랜드 보조 배경 */
  --color-primary-100: #EAE5FD;  /* purple-2 — bg-brand-tertiary */
  --color-primary-200: #E2D6FF;  /* purple-3 — 칩 호버 */
  --color-primary-300: #C6AFFF;  /* purple-5 */
  --color-primary-400: #9F76FF;  /* purple-8 */
  --color-primary-500: #7D2EFF;  /* purple-9 — 로고·검색 버튼·brand (기본) */
  --color-primary-600: #6F29E2;  /* purple-10 — foreground-brand, 링크 */
  --color-primary-700: #6001D2;  /* Grape Jelly — hover·focus 링 (2019 대표색) */
  --color-primary-800: #4C1C9B;  /* purple-12 */
  --color-primary-900: #3A1577;  /* purple-14 — 진한 보라 면 */

  /* Secondary - 2019 보조 보라 / 크리에이터 보라 */
  --color-secondary-500: #39007D;  /* Malbec 계열 — 메일 소개 페이지 진한 보라 (실측) */
  --color-accent-500:    #0063EB;  /* blue-9 — info·링크 강조 */

  /* Neutral - ymp-uh 팔레트 (푸른 기 도는 회색) */
  --color-neutral-0:    #FFFFFF;
  --color-neutral-50:   #F5F8FA;  /* marshmallow — 검색창 면 */
  --color-neutral-100:  #F0F3F5;  /* grey-hair — 구획 배경 */
  --color-neutral-300:  #E0E4E9;  /* dirty-seagull — 헤어라인 */
  --color-neutral-500:  #6E7780;  /* dolphin — 아이콘·캡션 */
  --color-neutral-700:  #5B636A;  /* battleship — 보조 글자 */
  --color-neutral-900:  #232A31;  /* batcave — 본문·제목 */
  --color-neutral-1000: #101518;  /* midnight — 다크 배경 */

  /* Semantic - UDS spectrum 9 / 1 */
  --color-success-bg: #DCFCD9;  /* green-1 */
  --color-success-fg: #017647;  /* green-9 — 시세 상승 */
  --color-warning-bg: #FFF1E2;  /* orange-1 */
  --color-warning-fg: #A64D1F;  /* orange-9 */
  --color-error-bg:   #FFEFEB;  /* red-1 */
  --color-error-fg:   #C62626;  /* red-9 — 시세 하락·오류 */
  --color-info-bg:    #EAF4F9;  /* blue-1 */
  --color-info-fg:    #0063EB;  /* blue-9 */

  /* Surface (배경 위계) */
  --bg-base:     #FFFFFF;             /* 홈·메일 본문 */
  --bg-subtle:   #F5F8FA;             /* 검색창·사이드 영역 */
  --bg-elevated: #FFFFFF;             /* 카드 */
  --bg-overlay:  rgba(16, 21, 24, 0.6); /* 모달 딤 (추정) */

  /* Text 위계 */
  --text-primary:    #232A31;  /* batcave — 본문·헤드라인 */
  --text-secondary:  #5B636A;  /* battleship — 출처·보조, 검색 placeholder */
  --text-tertiary:   #6E7780;  /* dolphin — 시간·캡션 */
  --text-on-primary: #FFFFFF;
  --text-disabled:   #B0B9C1;  /* gray-10 */

  /* Border */
  --border-default: #E0E4E9;  /* dirty-seagull */
  --border-subtle:  #F0F3F5;  /* grey-hair */
  --border-strong:  #B0B9C1;
  --border-focus:   #6001D2;  /* focus-visible 아웃라인 rgb(96 1 210 / 80%) */
}




.yh-btn { height: 40px; padding: 0 16px; border: 0; border-radius: var(--radius-full); font: 600 14px/18px 'YA Sans VF', 'Helvetica Neue', Arial, sans-serif; display: inline-flex; align-items: center; gap: 6px; cursor: pointer; transition: transform var(--duration-fast) var(--ease-out), background var(--duration-fast) var(--ease-out); }
.yh-btn:hover { transform: scale(1.03); }
.yh-btn:active { transform: scale(0.97); }
.yh-btn:focus-visible { outline: 4px solid rgba(96, 1, 210, 0.8); outline-offset: 0; }
.yh-btn--primary { background: var(--color-primary-500); color: var(--text-on-primary); }
.yh-btn--primary:hover { background: var(--color-primary-700); }
.yh-btn--secondary { background: var(--bg-base); color: var(--text-primary); box-shadow: inset 0 0 0 1px var(--border-default); }
.yh-btn--secondary:hover { box-shadow: inset 0 0 0 1px var(--border-strong); }
.yh-btn--ghost { background: transparent; color: var(--color-primary-600); }
.yh-btn--ghost:hover { background: var(--color-primary-50); }
.yh-btn--danger { background: var(--color-error-fg); color: #fff; }
.yh-btn:disabled { background: var(--border-subtle); color: var(--text-disabled); transform: none; cursor: not-allowed; }
.yh-btn.is-loading { color: transparent; position: relative; pointer-events: none; }
.yh-btn.is-loading::after { content: ""; position: absolute; left: 50%; top: 50%; width: 16px; height: 16px; margin: -8px 0 0 -8px; border: 2px solid rgba(255,255,255,0.4); border-top-color: #fff; border-radius: 50%; animation: yh-spin .8s linear infinite; }
@keyframes yh-spin { to { transform: rotate(360deg); } }
.yh-search { display: flex; align-items: center; height: 46px; max-width: 702px; padding: 0 4px 0 24px; border-radius: 100px; background: var(--bg-subtle); outline: 2px solid transparent; outline-offset: -2px; transition: outline var(--duration-base) var(--ease-in-out); }
.yh-search:hover { box-shadow: var(--shadow-md); outline-color: var(--border-default); }
.yh-search:focus-within { outline-color: var(--color-primary-500); background: var(--bg-base); }
.yh-search input { flex: 1; border: 0; background: transparent; font: 400 16px/20px 'YA Sans VF', Arial, sans-serif; color: var(--text-primary); caret-color: var(--color-primary-500); outline: none; }
.yh-search input::placeholder { color: var(--text-secondary); }
.yh-search__go { width: 60px; height: 40px; border-radius: 26px; background: var(--color-primary-500); display: grid; place-items: center; }
.yh-search__go:hover { background: var(--color-primary-700); }
.yh-input.is-error { outline-color: var(--color-error-fg); }
.yh-input:disabled { background: var(--border-subtle); color: var(--text-disabled); }
.yh-card { background: var(--bg-elevated); border-radius: var(--radius-lg); overflow: hidden; box-shadow: var(--shadow-sm); }
.yh-card:hover .yh-card__title { color: var(--color-primary-600); }
.yh-card--hero { position: relative; color: #fff; }                         /* 사진 위 검은 그라디언트 + 흰 제목 */
.yh-card--hero::after { content: ""; position: absolute; inset: 40% 0 0; background: linear-gradient(180deg, transparent, rgba(0,0,0,0.78)); }
.yh-card--outlined { box-shadow: inset 0 0 0 1px var(--border-default); }
.yh-card__title { font: 700 18px/22px 'Centra No2', 'Helvetica Neue', Arial, sans-serif; color: var(--text-primary); }
.yh-badge { display: inline-flex; align-items: center; height: 20px; padding: 0 6px; border-radius: var(--radius-sm); font: 600 11px/16px 'YA Sans VF', Arial, sans-serif; }
.yh-badge--solid { background: var(--color-primary-500); color: #fff; }
.yh-badge--subtle { background: var(--color-primary-100); color: var(--color-primary-700); }
.yh-badge--outline { box-shadow: inset 0 0 0 1px var(--border-strong); color: var(--text-secondary); }
.yh-ticker--up { color: var(--color-success-fg); }   /* 시세 +0.8% */
.yh-ticker--down { color: var(--color-error-fg); }
.yh-header { display: flex; align-items: center; gap: 24px; height: 72px; padding: 0 24px; background: var(--bg-base); }
.yh-tabs { display: flex; gap: 24px; box-shadow: inset 0 -1px 0 var(--border-default); }
.yh-tabs a { padding: 10px 0; font: 600 15px/20px 'YA Sans VF', Arial, sans-serif; color: var(--text-primary); text-decoration: none; }
.yh-tabs a:hover { color: var(--color-primary-600); }
.yh-tabs a.is-active { color: var(--color-primary-500); box-shadow: inset 0 -3px 0 var(--color-primary-500); }
